[metadata] {"type": "create", "filePath": "/workspace/repo/codex-rs/tui/src/chatwidget/warnings.rs", "content": "//! Deduplication state for warning messages shown in the chat history.
//!
//! Some warnings — notably the "model metadata not found" warning — can be
//! emitted repeatedly for the same model over the course of a session, which
//! clutters the conversation history. [`WarningDisplayState`] tracks which of
//! these warnings have already been shown so that per-model metadata warnings
//! are only surfaced once per model slug, while all other warnings continue to
//! be displayed every time.

use std::collections::HashSet;

/// Prefix of the model metadata warning, up to (but not including) the slug.
const MODEL_METADATA_PREFIX: &str = "Model metadata for `";
/// Suffix of the model metadata warning, following the slug.
const MODEL_METADATA_SUFFIX: &str =
    "` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.";

/// Tracks which warnings have already been displayed, enabling deduplication of
/// model-specific metadata warnings.
#[derive(Default)]
pub(super) struct WarningDisplayState {
    /// Model slugs for which a metadata warning has already been shown.
    seen_metadata_slugs: HashSet<String>,
}

impl WarningDisplayState {
    /// Decides whether `message` should be added to the chat history.
    ///
    /// For the model metadata warning, returns `true` the first time a given
    /// slug is seen and `false` for every subsequent occurrence of the same
    /// slug. For all other warnings, always returns `true`.
    pub(super) fn should_display(&mut self, message: &str) -> bool {
        match extract_metadata_slug(message) {
            Some(slug) => self.seen_metadata_slugs.insert(slug.to_string()),
            None => true,
        }
    }
}

/// Extracts the model slug from a model metadata warning, returning `None` if
/// `message` does not match the expected pattern exactly.
fn extract_metadata_slug(message: &str) -> Option<&str> {
    let rest = message.strip_prefix(MODEL_METADATA_PREFIX)?;
    rest.strip_suffix(MODEL_METADATA_SUFFIX)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn metadata_warning(slug: &str) -> String {
        format!(
            "Model metadata for `{slug}` not found. Defaulting to fallback metadata; this can degrade performance and cause issues."
        )
    }

    #[test]
    fn dedupes_metadata_warning_per_slug() {
        let mut state = WarningDisplayState::default();
        assert!(state.should_display(&metadata_warning("unknown-model")));
        assert!(!state.should_display(&metadata_warning("unknown-model")));
        // A different slug is still displayed the first time.
        assert!(state.should_display(&metadata_warning("other-model")));
        assert!(!state.should_display(&metadata_warning("other-model")));
    }

    #[test]
    fn always_displays_generic_warnings() {
        let mut state = WarningDisplayState::default();
        assert!(state.should_display("something went wrong"));
        assert!(state.should_display("something went wrong"));
        assert!(state.should_display("something went wrong"));
    }
}
